fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    result.extend_from_slice(&v1[..]); // Add all elements of v1
    result.extend_from_slice(&v2[..]); // Add all elements of v2
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(first.len() - 1 + second.len());
    result.extend_from_slice(&first[..first.len() - 1]); // Add all but the last element of first
    result.extend_from_slice(second); // Add all elements of second
    result
}

fn main() {
    // Example usage
    let a = vec![1, 2, 3, 4];
    let b = vec![5, 6, 7];
    
    let result = replace_last_element(&a, &b);
    println!("{:?}", result); // Output: [1, 2, 3, 5, 6, 7]
}